@RelationalHitting.stable_target_approx_rel
     : forall (MF : Type -> Type) (FI : Measure.SemanticMeasure MF),
       @Measure.SemanticMeasureCoreLaws MF FI ->
       forall FO : @Omega.SemanticOmega MF FI,
       @RelationalClosure.relational_bind MF FI ->
       @RelationalClosure.relational_zero MF FI FO ->
       forall (S1 S2 A B : Type) (kernel1 : S1 -> MF (PrimitiveStableHitting.stable_target S1 A))
         (kernel2 : S2 -> MF (PrimitiveStableHitting.stable_target S2 B))
         (SR : S1 -> S2 -> Prop) (AR : A -> B -> Prop),
       (forall (s : S1) (t : S2),
        SR s t ->
        @Measure.sem_lift MF FI (PrimitiveStableHitting.stable_target S1 A)
          (PrimitiveStableHitting.stable_target S2 B)
          (@RelationalHitting.stable_target_rel S1 S2 A B SR AR) (kernel1 s)
          (kernel2 t)) ->
       forall (fuel : nat) (x : PrimitiveStableHitting.stable_target S1 A)
         (y : PrimitiveStableHitting.stable_target S2 B),
       @RelationalHitting.stable_target_rel S1 S2 A B SR AR x y ->
       @Measure.sem_lift MF FI A B AR
         (@PrimitiveStableHitting.stable_target_approx MF FI FO S1 A kernel1 fuel x)
         (@PrimitiveStableHitting.stable_target_approx MF FI FO S2 B kernel2 fuel y)

