@Eq.Relation.ptree_hitting_pstrong
     : forall (E MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN)
         (NC : @Measure.SemanticMeasureCoreLaws MN NI) (FI : Measure.SemanticMeasure MF),
       @Measure.SemanticMeasureCoreLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @RelationalClosure.relational_bind MF FI ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       forall (A B : Type) (RR : A -> B -> Prop) (fuel : nat) (t : PTreeDefinition.ptree E MN A)
         (u : PTreeDefinition.ptree E MN B),
       @PStrong.pstrong E MN NI NC A B RR t u ->
       @Measure.sem_lift MF FI (UnifiedFrontier.stable_head E MN A)
         (UnifiedFrontier.stable_head E MN B)
         (@UnifiedFrontier.stable_head_rel E MN A B RR (@PStrong.pstrong E MN NI NC A B RR))
         (@PTreeKernel.ptree_hitting_approx E MN MF FI MX FO A fuel
            (@PTreeDefinition.observe E MN A t))
         (@PTreeKernel.ptree_hitting_approx E MN MF FI MX FO B fuel
            (@PTreeDefinition.observe E MN B u))

