@Eq.Iter.peutt_iter_unfold
     : forall (E MN MF : Type -> Type) (NI : Measure.SemanticMeasure MN),
       @Measure.SemanticMeasureCoreLaws MN NI ->
       forall (FI : Measure.SemanticMeasure MF) (FC : @Measure.SemanticMeasureCoreLaws MF FI)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @RelationalClosure.relational_bind MF FI ->
       @RelationalClosure.relational_mixed_bind MN MF NI FI MX ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (I R : Type) (step : I -> PTreeDefinition.ptree E MN (I + R)) (i : I),
       @PEutt.peutt E MN MF FI FC MX FO R R (@eq R) (@PTreeDefinition.PTree.iter E MN R I step i)
         (@PTreeDefinition.PTree.bind E MN (I + R) R (step i)
            (fun lr : I + R =>
             match lr with
             | @inl _ _ i' =>
                 {|
                   PTreeDefinition._observe :=
                     @PTreeDefinition.TauF E MN R (PTreeDefinition.ptree E MN R)
                       (@PTreeDefinition.PTree.iter E MN R I step i')
                 |}
             | @inr _ _ r =>
                 {|
                   PTreeDefinition._observe :=
                     @PTreeDefinition.RetF E MN R (PTreeDefinition.ptree E MN R) r
                 |}
             end))

